# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from 'react';

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorDetails {
  error: Error;
  errorInfo: ErrorInfo;
  timestamp: Date;
  componentStack: string;
}

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
  onError?: (details: ErrorDetails) => void;
  onReset?: () => void;
  resetKeys?: unknown[];
  isolate?: boolean;
}

interface ErrorBoundaryState {
  hasError: boolean;
  errorDetails: ErrorDetails | null;
  retryCount: number;
}

interface FallbackProps {
  error: Error;
  errorDetails: ErrorDetails;
  retryCount: number;
  resetError: () => void;
}

// ─── Logger ───────────────────────────────────────────────────────────────────

const logError = (details: ErrorDetails): void => {
  const { error, errorInfo, timestamp, componentStack } = details;

  console.group(
    `%c⚠ React Error Boundary — ${timestamp.toISOString()}`,
    'color: #ff4d4f; font-weight: bold; font-size: 14px;'
  );
  console.error('Error:', error.message);
  console.error('Stack Trace:', error.stack);
  console.error('Component Stack:', componentStack);
  console.error('Full ErrorInfo:', errorInfo);
  console.groupEnd();

  // Extend here: send to Sentry, Datadog, etc.
  // Sentry.captureException(error, { extra: { componentStack } });
};

// ─── Default Fallback UI ──────────────────────────────────────────────────────

const DefaultFallback: React.FC<FallbackProps> = ({
  error,
  retryCount,
  resetError,
}) => (
  <div role="alert" style={styles.container}>
    <div style={styles.card}>
      <div style={styles.iconWrapper}>
        <span style={styles.icon}>⚠</span>
      </div>

      <h2 style={styles.title}>Something went wrong</h2>

      <p style={styles.message}>
        An unexpected error occurred. You can try again or refresh the page.
      </p>

      <details style={styles.details}>
        <summary style={styles.summary}>Error details</summary>
        <pre style={styles.pre}>{error.message}</pre>
        {error.stack && (
          <pre style={{ ...styles.pre, marginTop: 8, fontSize: 11 }}>
            {error.stack}
          </pre>
        )}
      </details>

      <div style={styles.actions}>
        <button onClick={resetError} style={styles.retryButton}>
          ↺ Try Again {retryCount > 0 && `(${retryCount})`}
        </button>
        <button onClick={() => window.location.reload()} style={styles.reloadButton}>
          ⟳ Reload Page
        </button>
      </div>

      {retryCount >= 3 && (
        <p style={styles.hint}>
          Still failing? Try refreshing the page or contact support.
        </p>
      )}
    </div>
  </div>
);

// ─── Error Boundary Class ─────────────────────────────────────────────────────

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  static defaultProps: Partial<ErrorBoundaryProps> = {
    resetKeys: [],
    isolate: false,
  };

  state: ErrorBoundaryState = {
    hasError: false,
    errorDetails: null,
    retryCount: 0,
  };

  // Capture error and update state to trigger fallback render
  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { hasError: true };
  }

  // Log error details after render
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const details: ErrorDetails = {
      error,
      errorInfo,
      timestamp: new Date(),
      componentStack: errorInfo.componentStack ?? '',
    };

    logError(details);
    this.props.onError?.(details);

    this.setState({ errorDetails: details });
  }

  // Reset when resetKeys change (similar to react-error-boundary)
  componentDidUpdate(prevProps: ErrorBoundaryProps): void {
    const { resetKeys } = this.props;
    const { hasError } = this.state;

    if (
      hasError &&
      resetKeys?.length &&
      resetKeys.some((key, i) => key !== prevProps.resetKeys?.[i])
    ) {
      this.resetError();
    }
  }

  resetError = (): void => {
    this.props.onReset?.();
    this.setState((prev) => ({
      hasError: false,
      errorDetails: null,
      retryCount: prev.retryCount + 1,
    }));
  };

  render(): ReactNode {
    const { hasError, errorDetails, retryCount } = this.state;
    const { children, fallback, isolate } = this.props;

    if (hasError && errorDetails) {
      const fallbackProps: FallbackProps = {
        error: errorDetails.error,
        errorDetails,
        retryCount,
        resetError: this.resetError,
      };

      if (fallback) {
        return fallback(fallbackProps);
      }

      // Wrap in isolation div to prevent layout bleed
      return isolate ? (
        <div style={{ isolation: 'isolate' }}>
          <DefaultFallback {...fallbackProps} />
        </div>
      ) : (
        <DefaultFallback {...fallbackProps} />
      );
    }

    return children;
  }
}

// ─── Styles ───────────────────────────────────────────────────────────────────

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '200px',
    padding: '24px',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
  },
  card: {
    maxWidth: '520px',
    width: '100%',
    background: '#fff',
    border: '1px solid #ffa39e',
    borderRadius: '12px',
    padding: '32px',
    boxShadow: '0 4px 24px rgba(255, 77, 79, 0.12)',
    textAlign: 'center',
  },
  iconWrapper: {
    marginBottom: '16px',
  },
  icon: {
    fontSize: '48px',
    lineHeight: 1,
  },
  title: {
    margin: '0 0 12px',
    fontSize: '20px',
    fontWeight: 700,
    color: '#1a1a2e',
  },
  message: {
    margin: '0 0 20px',
    fontSize: '14px',
    color: '#595959',
    lineHeight: 1.6,
  },
  details: {
    textAlign: 'left',
    background: '#fff1f0',
    border: '1px solid #ffa39e',
    borderRadius: '8px',
    padding: '12px 16px',
    marginBottom: '24px',
  },
  summary: {
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 600,
    color: '#cf1322',
    userSelect: 'none',
  },
  pre: {
    margin: '8px 0 0',
    fontSize: '12px',
    color: '#820014',
    whiteSpace: 'pre-wrap',
    wordBreak: 'break-word',
    overflowX: 'auto',
  },
  actions: {
    display: 'flex',
    gap: '12px',
    justifyContent: 'center',
    flexWrap: 'wrap',
  },
  retryButton: {
    padding: '10px 24px',
    background: '#ff4d4f',
    color: '#fff',
    border: 'none',
    borderRadius: '8px',
    fontSize: '14px',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'background 0.2s',
  },
  reloadButton: {
    padding: '10px 24px',
    background: 'transparent',
    color: '#595959',
    border: '1px solid #d9d9d9',
    borderRadius: '8px',
    fontSize: '14px',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'border-color 0.2s',
  },
  hint: {
    marginTop: '16px',
    fontSize: '12px',
    color: '#8c8c8c',
  },
};

export default ErrorBoundary;
export type { ErrorBoundaryProps, FallbackProps, ErrorDetails };
```

## Usage Examples

```tsx
// App.tsx — Basic usage
import ErrorBoundary from './ErrorBoundary';

// 1. Basic wrapping
function App() {
  return (
    <ErrorBoundary>
      <MyComponent />
    </ErrorBoundary>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 2. Custom fallback UI
function AppWithCustomFallback() {
  return (
    <ErrorBoundary
      fallback={({ error, resetError, retryCount }) => (
        <div className="my-error-ui">
          <h3>Oops! {error.message}</h3>
          <button onClick={resetError}>Retry ({retryCount})</button>
        </div>
      )}
    >
      <MyComponent />
    </ErrorBoundary>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 3. With error reporting + reset callback
function AppWithReporting() {
  const handleError = (details) => {
    // Send to your error tracking service
    fetch('/api/log-error', {
      method: 'POST',
      body: JSON.stringify({
        message: details.error.message,
        stack: details.error.stack,
        componentStack: details.componentStack,
        timestamp: details.timestamp,
      }),
    });
  };

  return (
    <ErrorBoundary
      onError={handleError}
      onReset={() => console.log('Error boundary reset')}
    >
      <MyComponent />
    </ErrorBoundary>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 4. Auto-reset when route/key changes
function AppWithResetKeys() {
  const { pathname } = useLocation();
  const [userId, setUserId] = useState(null);

  return (
    // Resets automatically when pathname or userId changes
    <ErrorBoundary resetKeys={[pathname, userId]}>
      <MyComponent />
    </ErrorBoundary>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 5. Granular boundaries per section (recommended pattern)
function Dashboard() {
  return (
    <div>
      <ErrorBoundary isolate>
        <Sidebar />
      </ErrorBoundary>

      <main>
        <ErrorBoundary isolate>
          <Header />
        </ErrorBoundary>

        <ErrorBoundary
          isolate
          fallback={({ resetError }) => (
            <div>Widget failed. <button onClick={resetError}>Reload</button></div>
          )}
        >
          <DataWidget />
        </ErrorBoundary>
      </main>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 6. Buggy component to test with
function BuggyCounter() {
  const [count, setCount] = React.useState(0);

  if (count === 3) {
    throw new Error(`Simulated crash at count=${count}`);
  }

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(c => c + 1)}>
        Increment (crashes at 3)
      </button>
    </div>
  );
}
```

## Key Design Decisions

| Feature | Approach |
|---|---|
| **Error capture** | `getDerivedStateFromError` + `componentDidCatch` |
| **Logging** | Structured `console.group` with timestamp; extend for Sentry/Datadog |
| **Retry tracking** | `retryCount` increments on each reset, shown in button |
| **Auto-reset** | `resetKeys` prop triggers reset when values change |
| **Custom UI** | Render prop `fallback` for full control |
| **Isolation** | `isolate` prop prevents layout bleed via CSS isolation |
| **TypeScript** | Fully typed props, state, and exported interfaces |

> **Note:** Error boundaries only catch errors in **render**, **lifecycle methods**, and **constructors** — not in event handlers or async code. Use `try/catch` or `window.onerror` for those cases.
